const GRADERS = ['PSA', 'BGS', 'CGC', 'Other'];
function conditionsFor(cat) {
  return CONDITIONS[cat] || CONDITIONS.figures;
}

// helpers
function cat(sku) {
  return CATALOGUE.find(c => c.sku === sku);
}
// Manufacturer reference code printed on the box. Seed/official catalogue entries carry it as
// their sku; user-contributed entries supply it explicitly (refCode) or not at all — we never
// surface the internal id we generate for them.
function skuOf(c) {
  if (!c) return null;
  if (c.refCode) return c.refCode;
  if (c.noSku) return null;
  if (!c.sku || /^U\d{8,}$/.test(String(c.sku))) return null;
  return c.sku;
}
function addToCatalogue(entry) {
  CATALOGUE.push(entry);
}
function user(h) {
  return USERS[h] || ME;
}
function listing(id) {
  return LISTINGS.find(l => l.id === id) || MARKET_SEED.find(l => l.id === id);
}
function presenceOf(h) {
  return PRESENCE[h] || 'active recently';
}
function termsOf(id) {
  return LISTING_TERMS[id] || DEFAULT_TERMS;
}
// map free-text condition to a standardised ladder rung (§9.9)
function gradeOf(cond) {
  const s = (cond || '').toLowerCase();
  if (s.includes('misb') || s.includes('sealed') || s.includes('factory')) return 'Sealed / MISB';
  if (s.includes('bnib') || s.includes('new')) return 'Like new';
  if (s.includes('mint')) return 'Mint';
  if (s.includes('good')) return 'Good';
  if (s.includes('fair')) return 'Fair';
  if (s.includes('parts')) return 'For parts';
  return 'Mint';
}
function postModeOf(id) {
  return COM_POSTMODE[id] || 'open';
}
function adminsOf(id) {
  const c = COMMUNITIES.find(x => x.id === id);
  return COM_ADMINS[id] || (c ? [{
    handle: c.founder,
    role: 'Founder'
  }] : []);
}
// Role with a runtime override applied (promotions/demotions made in Manage community are
// session-local state, not baked into the seed data) — pass useAppState().communityRoleOverrides.
function roleOfWithOverride(id, handle, overrides) {
  const o = overrides && overrides[id];
  if (o && Object.prototype.hasOwnProperty.call(o, handle)) return o[handle];
  return roleOf(id, handle);
}
const ROLE_RANK = {
  Founder: 3,
  Admin: 2,
  Mod: 1
};
function roleCanFullAdmin(role) {
  return role === 'Founder' || role === 'Admin';
}
function roleCanManage(role) {
  return !!role;
}
const COMMUNITY_RULES_MAX = 900;
function communityApproved(com) {
  return !com || com.status !== 'pending';
}
// Roster of member handles for a community — admins first, then seed members, then a sample of users.
function membersOf(id) {
  const admins = adminsOf(id).map(a => a.handle);
  const seed = COM_MEMBERS[id] || [];
  const extra = Object.keys(USERS);
  const all = [...admins, ...seed, ...extra];
  return all.filter((h, i) => all.indexOf(h) === i); // dedupe, preserve order
}
function joinRequestsOf(id) {
  return COM_JOIN_REQUESTS[id] || [];
}
function pendingPostsOf(id) {
  return COM_PENDING_POSTS[id] || [];
}
function roleOf(id, handle) {
  const a = adminsOf(id).find(x => x.handle === handle);
  return a ? a.role : null;
}
// ownership-stats parts, e.g. ['58 action figures', '13 designer toys']
function ownStats(u) {
  let owns;
  if (u.handle === 'you') {
    owns = {};
    MY_ITEMS.filter(i => i.status !== 'wishlist' && i.status !== 'intel').forEach(i => {
      const c = cat(i.sku);
      if (!c) return;
      owns[c.cat] = (owns[c.cat] || 0) + 1;
    });
  } else owns = OWNS[u.handle] || {};
  return Object.entries(owns).filter(([, n]) => n > 0).map(([k, n]) => `${n} ${OWN_LABELS[k] || k}`);
}

